changeSet.sql:
create or alter procedure [metrics].[GenerateScore] @assetUid uniqueidentifier, @effectiveDate date, @scoreType int, @responseScore decimal(8,6) output, @scoreChanged bit output as begin set nocount on;
-- Get the allocationUid. declare @allocationUid uniqueidentifier, @isCurrentDate bit = iif(cast(getutcdate() as date) = @effectiveDate, 1, 0);
select @allocationUid = al.Uid from dbo.Asset a inner join dbo.AssetType t on t.ID = a.AssetTypeID and a.Uid = @assetUid inner join metrics.Allocation al on al.AssetTypeUid = t.Uid and al.ScoreType = @scoreType;
if @allocationUid is null begin return; end
-- Store the value of measures. declare @measures table (ID Int IDENTITY(1,1) NOT NULL, ParentVersionUid uniqueidentifier, VersionUid uniqueidentifier, MatchUid uniqueidentifier, OtherMatches nvarchar(max), Evidence nvarchar(max), Weight decimal(8,6), AdjustedWeight decimal(8,6), ContributionWeight decimal(8,6), Value decimal(8,6), RawValue decimal(8,6), AdjustedValue decimal(8,6), ItemUid uniqueidentifier null, DoesExist bit null, index cx_measure clustered(ID), index ix_measure_ParentVersionUid (ParentVersionUid), index ix_measure_ItemUid (ItemUid) );
if @scoreType = 1 begin insert into @measures ( ParentVersionUid, VersionUid, Value, RawValue, Weight, MatchUid, OtherMatches, Evidence ) select ParentVersionUid, VersionUid, Value, Value, Weight, MatchUid, coalesce(OtherMatches, '[]'), '{}' from metrics.GetGovernanceScore(@assetUid, @effectiveDate)
-- Clean out the relevant record as we just processed them above, in case we have any External measures. delete metrics.ExternalMeasureResult where AssetUid = @assetUid and EffectiveDate = @effectiveDate; end;
if @scoreType = 2 begin insert into @measures ( ParentVersionUid, VersionUid, Value, RawValue, Weight, MatchUid, OtherMatches, Evidence) select ParentVersionUid, VersionUid, Value, RawValue, Weight, MatchUid, coalesce(OtherMatches, '[]'), Evidence from metrics.GetDataQualityScore(@assetUid, @effectiveDate) end;
-- Determines if there are any measures present that are NOT measure groups. If ONLY measure groups, then no measure was relevant, meaning - a dead score. declare @IsScoreDead bit = 0; select @IsScoreDead = iif(count(1) > 0, 0, 1) from @measures m inner join metrics.AssetVersion v on v.Uid = m.VersionUid inner join metrics.Asset a on a.Uid = v.AssetUid and a.IsGroup = 0;
-- Common logic to determine weight rebalancing, within each measure group, or at root. update m set m.AdjustedWeight = m.Weight / [level].Total from @measures m cross apply ( select sum(Weight) as Total from @measures where (m.ParentVersionUid is not null and ParentVersionUid = m.ParentVersionUid) or (m.ParentVersionUid is null and ParentVersionUid is null) ) as [level];
-- Determine what the contributing weight, to the overall score, could be, by starting at the root, and traversing down through each measure group. -- In the second part of the CTE, you multiply the adjusted weight by the parent group's Contributon weight, as it is only a portion of the parent's contribution. with h as ( select ParentVersionUid, VersionUid, AdjustedWeight as ContributionWeight from @measures m where ParentVersionUid is null union all select c.ParentVersionUid, c.VersionUid, cast((c.AdjustedWeight * h.ContributionWeight) as decimal(8,6)) as ContributionWeight from @measures c inner join h on h.VersionUid = c.ParentVersionUid )
-- Update the calculated contribution weight, and figure out the overall value for the measure, towards the score. update m set m.ContributionWeight = h.ContributionWeight, m.AdjustedValue = h.ContributionWeight * m.Value from @measures m inner join h on h.VersionUid = m.VersionUid;
-- Common to deal with AdjustedValue on the measure groups, as they do not get a value directly (they are a calculation of the sum of their children) -- HINT: Those records that have a NULL value for AdjustedValue are actually measure groups. declare @groups table (Uid uniqueidentifier, [Level] int); with h as ( select ParentVersionUid, VersionUid, cast(1 as int) as [Level] from @measures where ParentVersionUid is null and AdjustedValue is null union all select c.ParentVersionUid, c.VersionUid, h.[Level] + 1 as [Level] from @measures c inner join h on h.VersionUid = c.ParentVersionUid and c.AdjustedValue is null ) insert into @groups select VersionUid, [Level] from h; declare @currentLevel int; select @currentLevel = max([Level]) from @groups;
-- Loop through each level starting with the bottom level, and work your way up toward the root of the score. -- This calculates the adjusted value for each group, as we roll up to the root. while @currentLevel >= 1 begin update m set m.AdjustedValue = t.AdjustedValue from @measures m inner join @groups g on g.Uid = m.VersionUid and g.[Level] = @currentLevel cross apply ( select sum(AdjustedValue) as AdjustedValue from @measures where ParentVersionUid = m.VersionUid ) t
set @currentLevel = @currentLevel - 1; end
-- Get the actual score. declare @Score decimal(8,6); select @Score = sum(coalesce(AdjustedValue, 0)) from @measures where ParentVersionUid is null;
if @Score is null begin set @Score = 0 end
-- Get the current score for the asset. declare @CurrentScore decimal(8,6), @CurrentHash varchar(50) = '', @MostRecentEndDate date; -- will be used to determine if we should reactivate dead score.
-- Determine what the previous score and fingerprint (hash) of the score was. select top 1 @CurrentScore = [Value], @CurrentHash = coalesce(VersionValueHash, ''), @MostRecentEndDate = EndDate from metrics.Score where AllocationUid = @allocationUid and AssetUid = @assetUid and EffectiveDate <= @effectiveDate order by EffectiveDate desc;
declare @Current date = getutcdate(), @DateDifference int; set @DateDifference = DATEDIFF(dd, @MostRecentEndDate, @Current); if @DateDifference <= 1 begin set @isCurrentDate = 1 end
-- select @CurrentScore as [Current], @Score as [New] -- DEBUG PURPOSES
-- Determine which "most-recent" measures are already associated with the asset declare @measuresMostRecent table ( ItemUid uniqueidentifier, AssetVersionUid uniqueidentifier, DecimalValue [float], ConditionUid uniqueidentifier, AdjustedWeight decimal(8,6), AdjustedMaxWeight decimal(8,6), [Value] [bit] NULL, index cx_measure clustered(AssetVersionUid) );
insert into @measuresMostRecent(ItemUid,AssetVersionUid,DecimalValue, ConditionUid,AdjustedWeight,AdjustedMaxWeight,[Value]) select i.Uid as ItemUid, i.AssetVersionUid, i.DecimalValue, i.ConditionUid, i.AdjustedWeight, i.AdjustedMaxWeight, i.[Value] from metrics.Score s inner join metrics.ScoreItemLink l on l.ScoreUid = s.Uid inner join metrics.ScoreItem i on i.Uid = l.ScoreItemUid where s.AllocationUid = @allocationUid and s.AssetUid = @assetUid and s.EffectiveDate <= @effectiveDate;
update m set m.ItemUid = ex.ItemUid, m.DoesExist = iif(ex.ItemUid is not null, 1, 0) from @measures m left join @measuresMostRecent ex on ex.AssetVersionUid = m.VersionUid and ex.DecimalValue = m.AdjustedValue;
--select @Score, @CurrentScore
-- Is there anything to update for this score? declare @prehash nvarchar(max), @Hash varchar(50); select @prehash = string_agg('[' + lower(cast(VersionUid as nvarchar(50))) + '|' + cast(RawValue as nvarchar(10)) + ']', ';') from @measures --select @prehash = string_agg('[' + lower(cast(VersionUid as nvarchar(50))) + '|' + Evidence + '|' + cast(RawValue as nvarchar(10)) + ']', ';') from @measures select @Hash = [utility].[GetHash](@prehash)
-- Add new itemUids for those records that do not have a match. update @measures set ItemUid = newid() where ItemUid is null;
-- Add new score records. declare @NewScoreUid uniqueidentifier = newid(), @runDate datetime = getutcdate(), @shouldAddScore bit = 1;
-- Compare the current fingerprint with the previous fingerprint. If same, we should NOT create the score. if @Hash = @CurrentHash begin set @shouldAddScore = 0; end
--select @Hash, @CurrentHash, @shouldAddScore
if @IsScoreDead = 1 begin declare @mostRecentDate date, @endDate date;
select @mostRecentDate = max(EffectiveDate) from metrics.Score where AllocationUid = @allocationUid and AssetUid = @assetUid;
select @NewScoreUid = Uid, @endDate = EndDate from metrics.Score where AllocationUid = @allocationUid and AssetUid = @assetUid and EffectiveDate = @mostRecentDate;
if @NewScoreUid is not null and @endDate is null begin update metrics.Score set RunDate = @runDate, EndDate = @runDate where Uid = @NewScoreUid; end
set @scoreChanged = 0; end else -- Score is ALIVE. begin if exists(select 1 from metrics.Score where AllocationUid = @allocationUid and AssetUid = @assetUid and EffectiveDate = @effectiveDate) begin select @NewScoreUid = Uid from metrics.Score where AllocationUid = @allocationUid and AssetUid = @assetUid and EffectiveDate = @effectiveDate;
update metrics.Score set [Value] = coalesce(@Score, 0), RunDate = @runDate, VersionValueHash = @Hash, EndDate = iif(@isCurrentDate = 1, null, EndDate) where Uid = @NewScoreUid; end else begin if @shouldAddScore = 1 begin insert into metrics.Score (AssetUid, EffectiveDate, [Value], RunDate, Uid, AllocationUid, [Log], VersionValueHash) values (@assetUid, @effectiveDate, coalesce(@Score, 0), @runDate, @NewScoreUid, @allocationUid, '{}', @Hash); end end
-- End-date older scores that do not yet have an end date. update t set t.EndDate = iif(e.NextEffectiveDate is null, null, DATEADD(d, -1, e.NextEffectiveDate)) from metrics.Score t outer apply ( select min(EffectiveDate) as NextEffectiveDate from metrics.Score where AllocationUid = t.AllocationUid and AssetUid = t.AssetUid and EffectiveDate > t.EffectiveDate ) e where t.AllocationUid = @allocationUid and t.AssetUid = @assetUid and t.EndDate is null;
if @shouldAddScore = 1 begin set @responseScore = coalesce(@Score, 0); set @scoreChanged = 1;
merge into metrics.ScoreItem as t using ( select ItemUid , VersionUid , @runDate as [UpdatedOn] , @runDate as RunDate , MatchUid as ConditionUid , OtherMatches as OtherConditions , Evidence , [RawValue] as DecimalValue , iif([Value] = 1, 1, 0) as [Value] , AdjustedWeight , ContributionWeight as AdjustedMaxWeight , AdjustedValue as DisplayWeight , ContributionWeight as DisplayMaxWeight from @measures ) as s on (t.Uid = s.ItemUid) when matched then update set t.RunDate = s.RunDate , t.UpdatedOn = s.UpdatedOn , t.ConditionUid = s.ConditionUid , t.OtherConditions = s.OtherConditions , t.[Evidence] = s.[Evidence] , t.[Value] = s.[Value] , t.[DecimalValue] = s.[DecimalValue] , t.[AdjustedWeight] = s.[AdjustedWeight] , t.[AdjustedMaxWeight] = s.[AdjustedMaxWeight] , t.[DisplayWeight] = s.[DisplayWeight] , t.[DisplayMaxWeight] = s.[DisplayMaxWeight] when not matched then insert ([Uid], [AssetVersionUid], [UpdatedOn], [RunDate] , [ConditionUid], [OtherConditions], [Evidence] , [Value], [DecimalValue], [AdjustedWeight], [AdjustedMaxWeight], [DisplayWeight], [DisplayMaxWeight]) values (s.ItemUid, s.VersionUid, s.UpdatedOn, s.RunDate , s.ConditionUid, s.OtherConditions, s.[Evidence] , s.[Value], s.DecimalValue, s.AdjustedWeight, s.AdjustedMaxWeight, s.DisplayWeight, s.DisplayMaxWeight);
delete metrics.ScoreItemLink where ScoreUid = @NewScoreUid;
insert into metrics.ScoreItemLink select @NewScoreUid as ScoreUid, ItemUid as ScoreItemUid from @measures; end end
-- select * from @measures order by ParentVersionUid -- DEBUG PURPOSES return; -- needed for output parameters end
